c.cpp:
class Solution {
public:
    int f(int x){
        int s=0;
        for(int d=2;d*d<=x;d++) while(x%d==0){s+=d;x/=d;}
        if(x>1)s+=x;
        return s;
    }
    int smallestValue(int n){
        while(true){int nx=f(n); if(nx==n)return n; n=nx;}
    }
};

